const j = $input.first().json;
if (!j.artifact_type) return [];
const RUBRICS = {
  extraction: [
    'You judge whether structured data extracted from an email is FAITHFUL to the email text. Faithfulness means: nothing INVENTED. It does NOT mean completeness or your preferred interpretation.',
    'RULE 1 - NULLS ARE ALWAYS CORRECT: a null or empty field is NEVER a violation. Null means the extractor declined to guess. Only NON-NULL values can be violations.',
    'RULE 2 - VERBATIM fields (contact_name, contact_email, company, budget_value, location): a non-null value must be supported by the email text or headers. Obvious implications count as support: Rs. / rupees / lakh implies budget_currency=INR; a signature or From-Name supports contact_name.',
    'RULE 3 - DERIVED fields (urgency, product_interest): categorical judgments by design. Flag ONLY when a non-null value has NO textual basis at all. Calibration disagreements (you would have chosen high instead of medium) are NOT violations.',
    'Score 5: no violations. Score 3: one borderline stretch worth noting (still no fabrication). Score 1: any non-null value with no support in the email.',
    'violations must ONLY contain non-null fabricated values, as field=value.'
  ].join('\n'),
  draft: [
    'You judge a sales reply draft for GROUNDEDNESS and TONE ADHERENCE.',
    'Groundedness: the draft may mention ONLY the allowed_products (names/prices as given). Any invented discount, delivery promise, stock claim, warranty, or product = violation.',
    'Tone: compare against tone_instruction.',
    'Score 5: fully grounded AND clearly matches the tone. Score 3: grounded but tone generic/flat. Score 2 or 1 (AUTOMATIC on any invented commercial claim): fabrication present.',
    'List every fabricated claim in violations verbatim.'
  ].join('\n'),
  reasons: [
    'You judge whether lead-qualification reasons are FACTUAL.',
    'Each reason must reference facts in extraction or factors in rubric_breakdown. Paraphrase is fine; new facts are not.',
    'Score 5: all reasons traceable. Score 3: one vague but harmless reason. Score 2 or 1: any invented fact.',
    'List invented claims in violations.'
  ].join('\n')
};
const system = RUBRICS[j.artifact_type] +
  '\nRespond with ONLY JSON: {"score_1_5": 1|2|3|4|5, "violations": string[], "reasoning": string (max 50 words)}.';
return [{ json: { ...j, judge_system: system, judge_user: JSON.stringify(j.payload), __t0: Date.now() } }];

const raw = $input.first().json;
const src = $('Build Judge Prompt').first().json;
let verdict = null;
try { verdict = JSON.parse(raw.choices[0].message.content); } catch (e) {}
const usage = raw.usage || {};
const valid = !!(verdict && Number.isInteger(verdict.score_1_5) && verdict.score_1_5 >= 1 && verdict.score_1_5 <= 5 && Array.isArray(verdict.violations));
return [{ json: {
  artifact_type: src.artifact_type, artifact_ref: src.artifact_ref,
  lead_id: src.lead_id, business_id: src.business_id, trace_id: src.trace_id || null,
  valid, score: valid ? verdict.score_1_5 : null,
  violations: valid ? verdict.violations : ['judge output invalid'],
  reasoning: valid ? String(verdict.reasoning || '').slice(0, 500) : 'unparseable judge output',
  latency_ms: Date.now() - (src.__t0 || Date.now()),
  input_tokens: usage.prompt_tokens || null, output_tokens: usage.completion_tokens || null,
  cost_usd: usage.prompt_tokens != null ? +(((usage.prompt_tokens * 2.50 + usage.completion_tokens * 10.0) / 1e6).toFixed(6)) : null
} }];
